// SPDX-License-Identifier: GPL-3.0-or-later
//! The marks of the networks a part is shared to, as SVG path data (20×20), for the editor's list of them. Drawn from
//! Simple Icons (CC0); each mark belongs to its owner.

use crate::theme::Rgba;

/// A network's mark and its colour (`None`: black, drawn in the colour of the text so it shows on a dark theme).
#[derive(Debug, Clone, Copy)]
pub struct Brand {
    pub path: &'static str,
    pub colour: Option<Rgba>,
}

/// The mark of `network` (`vixeeny_encode::share::Network`, lower case).
pub fn brand(network: &str) -> Option<Brand> {
    let (path, colour) = match network {
        "discord" => (DISCORD, Some(Rgba::hex(0x5865F2, 255))),
        "x" => (X, None),
        "youtube" => (YOUTUBE, Some(Rgba::hex(0xFF0000, 255))),
        "tiktok" => (TIKTOK, None),
        "bluesky" => (BLUESKY, Some(Rgba::hex(0x1185FE, 255))),
        "reddit" => (REDDIT, Some(Rgba::hex(0xFF4500, 255))),
        "instagram" => (INSTAGRAM, Some(Rgba::hex(0xFF0069, 255))),
        "threads" => (THREADS, None),
        "telegram" => (TELEGRAM, Some(Rgba::hex(0x26A5E4, 255))),
        _ => return None,
    };
    Some(Brand { path, colour })
}

