#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_mark_is_drawn() {
        for network in ["discord", "x", "youtube", "tiktok", "bluesky", "reddit", "instagram", "threads", "telegram"] {
            let mark = brand(network).unwrap_or_else(|| panic!("{network}"));
            assert!(crate::svg::parse(mark.path).is_some_and(|f| !f.is_empty()), "{network}");
        }
        assert!(brand("myspace").is_none());
    }
}
